for(const form of document.querySelectorAll('[data-chart-form]'))form.addEventListener('submit',event=>{const button=event.submitter;if(button?.value==='finish'){const status=document.createElement('p');status.setAttribute('role','status');status.className='compass-success';status.textContent='Charting your Gold Trail… saving your profile and matching real resources.';form.append(status);}else if(form.action.endsWith('/guide/')){const status=document.createElement('p');status.setAttribute('role','status');status.textContent='Looking through the Gold Trails library…';form.append(status);}});
// Keep None yet mutually exclusive, without disabling keyboard or no-JS form use.
for(const input of document.querySelectorAll('input[name="equipment"]'))input.addEventListener('change',()=>{if(!input.checked)return;for(const other of document.querySelectorAll('input[name="equipment"]'))if(other!==input&&(input.value==='none'||other.value==='none'))other.checked=false;});
